/* eslint-disable react/jsx-max-depth */
import React, { useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useIntl } from 'react-intl';
import { VictoryPie, VictoryContainer } from 'victory';
import colors from 'Styles/colors';
import { addFilter } from 'store/Filters/actions';
import { CLOSED_FILTERS, CONFIRMED_FLAG_FILTERS, DASHBOARD_FILTERS } from 'store/Filters/constants';
import { isFilteringBy } from 'store/Filters/selectors';
import { selectCurrentWorkspace } from 'store/Faraday/selectors';
import { redirect } from 'store/Router/actions';
import { selectPreferences } from 'store/Preferences/selectors';
import SpinnerComponent from 'Common/Components/SpinnerContainer';
import {
  Wrapper,
  Empty,
  ContentWrapper,
  PieWrapper,
  CenterLabel,
  CenterValue,
  CenterBand,
  BarSection,
  StackedBar,
  GreenSegment,
  PinkSegment,
  CountLabels,
  CountLabel,
  AvgRiskIcon
} from './styled';
import TitleWrapper from '../components/TitleWrapper';

const RISK_COLOR = {
  purple: '#9B59B6',
  red: '#dc4a4a',
  orange: '#f1ae62',
  green: '#88cc3f'
};

const getColorKey = (risk) => {
  if (risk >= 90) return 'purple';
  if (risk >= 70) return 'red';
  if (risk >= 40) return 'orange';
  return 'green';
};

const WorkspaceRisk = () => {
  const dispatch = useDispatch();
  const { theme } = useSelector(selectPreferences);
  const stats = useSelector(
    (state) => state.dashboard?.tools?.[3]?.data?.stats ?? {}
  );
  const isFetching = useSelector(
    (state) => state.dashboard?.loadingState?.summary ?? false
  );
  const workspaceSelected = useSelector((state) =>
    selectCurrentWorkspace(state)
  );
  const { confirmed } = CONFIRMED_FLAG_FILTERS;
  const { closed } = CLOSED_FILTERS;
  const isFilteringByConfirm = useSelector((state) => isFilteringBy(state, 'vulns', confirmed));
  const isFilteringByClosed = useSelector((state) => isFilteringBy(state, 'vulns', closed));
  const intl = useIntl();
  const translations = useMemo(
    () => ({
      title: intl.formatMessage({
        id: 'dashboard.widgets.workspaceRisk.title'
      }),
      info: intl.formatMessage({ id: 'dashboard.widgets.workspaceRisk.info' }),
      empty: intl.formatMessage({
        id: 'dashboard.widgets.workspaceRisk.empty'
      }),
      distribution: intl.formatMessage({
        id: 'dashboard.widgets.workspaceRisk.distribution'
      }),
      bandCritical: intl.formatMessage({
        id: 'dashboard.widgets.workspaceRisk.band.critical'
      }),
      bandHigh: intl.formatMessage({
        id: 'dashboard.widgets.workspaceRisk.band.high'
      }),
      bandMedium: intl.formatMessage({
        id: 'dashboard.widgets.workspaceRisk.band.medium'
      }),
      bandLow: intl.formatMessage({
        id: 'dashboard.widgets.workspaceRisk.band.low'
      })
    }),
    [intl]
  );

  const totalRiskAvg = stats?.total_risk_avg ?? null;
  const aboveRiskAvgCount = stats?.above_risk_avg_count ?? 0;
  const belowRiskAvgCount = stats?.below_risk_avg_count ?? 0;
  const totalVulns = stats?.total_vulns ?? 0;

  const handleRiskClick = (op) => {
    dispatch(addFilter('vulns', DASHBOARD_FILTERS.vulnsByRiskAvg(op, totalRiskAvg)));
    if (isFilteringByConfirm) dispatch(addFilter('vulns', confirmed));
    if (isFilteringByClosed) dispatch(addFilter('vulns', closed));
    dispatch(redirect(`/manage/${workspaceSelected}`));
  };

  const handleAboveClick = () => handleRiskClick('>=');
  const handleBelowClick = () => handleRiskClick('<');

  if (isFetching) return <SpinnerComponent height="250px" />;

  const graphBarColor = theme === 'dark' ? colors.dark9 : colors.blue8;
  const colorKey = getColorKey(totalRiskAvg);
  const color = RISK_COLOR[colorKey];
  const bandLabel = {
    purple: translations.bandCritical,
    red: translations.bandHigh,
    orange: translations.bandMedium,
    green: translations.bandLow
  }[colorKey];

  const total = aboveRiskAvgCount + belowRiskAvgCount;
  const belowPct =
    total > 0 ? Math.round((belowRiskAvgCount / total) * 100) : 0;
  const abovePct = 100 - belowPct;

  return (
    <Wrapper>
      <TitleWrapper
        title={ translations.title }
        info={ translations.info }
        icon={ <AvgRiskIcon /> }
      />
      {totalRiskAvg === null || totalVulns === 0
        ? (
        <Empty>{translations.empty}</Empty>
          )
        : (
        <>
          <ContentWrapper>
            <PieWrapper>
              <VictoryPie
                startAngle={ -90 }
                endAngle={ 90 }
                data={ [
                  { name: 'risk', value: totalRiskAvg },
                  { name: 'rest', value: 100 - totalRiskAvg }
                ] }
                x="name"
                y="value"
                style={ {
                  data: {
                    fill: ({ datum }) =>
                      datum.name === 'risk' ? color : graphBarColor,
                    stroke: 'none'
                  }
                } }
                height={ 220 }
                width={ 300 }
                radius={ 75 }
                innerRadius={ 55 }
                cornerRadius={ ({ datum }) => (datum.name === 'risk' ? 15 : 0) }
                labels={ () => '' }
                containerComponent={ <VictoryContainer responsive={ false } /> }
              />

              <CenterLabel>
                <CenterValue>{totalRiskAvg.toFixed(1)}</CenterValue>
                <CenterBand>{bandLabel}</CenterBand>
              </CenterLabel>
            </PieWrapper>
          </ContentWrapper>

          <BarSection>
            <CountLabels>
              <CountLabel onClick={ handleBelowClick }>
                {translations.distribution}
              </CountLabel>
            </CountLabels>{' '}
            <StackedBar>
              <GreenSegment
                style={ { width: `${belowPct}%` } }
                onClick={ handleBelowClick }
              >
                {belowPct}%
              </GreenSegment>
              <PinkSegment
                style={ { width: `${abovePct}%` } }
                onClick={ handleAboveClick }
              >
                {abovePct}%
              </PinkSegment>
            </StackedBar>
          </BarSection>
        </>
          )}
    </Wrapper>
  );
};

export default WorkspaceRisk;
